import { Component, h, Prop, Element } from '@stencil/core';

@Component({
  tag: 'std-stepper',
  styleUrl: 'std-stepper.css',
  shadow: true
})
export class StdStepperComponent {
  @Prop() label: string;
  @Prop() description: string;
  @Prop() classes: string;

  @Element() el: HTMLElement;

  steps: number;

  componentWillLoad() {
    this.steps = this.el.querySelectorAll('[step]').length;
  }

  render() {
    return (
      <section class={`flex flex-col gap-6 bg-alternative-light px-4 lg:px-6 py-8 ${this.classes}`}>
        <div class="flex flex-col gap-4 max-w-4xl mx-auto text-center">
          {this.label && <h1 class="text-3xl font-bold">{this.label}</h1>}
          {this.description && <p>{this.description}</p>}
        </div>
        <ul class="flex flex-col lg:flex-row gap-1 lg:gap-0 w-full max-w-4xl mx-auto">
          <slot />
        </ul>
      </section>
    );
  }
}
